def cache_sim(capacity, ttl, ops):
    cache = {}  # key -> value
    write_time = {}  # key -> time when it was written
    access_order = []  # list of keys in order of most recent access
    results = []

    def is_expired(key, current_time):
        if key not in write_time:
            return True
        return current_time >= write_time[key] + ttl

    def mark_accessed(key):
        if key in access_order:
            access_order.remove(key)
        access_order.append(key)

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op

            # Check if key is expired
            if key in cache and is_expired(key, t):
                del cache[key]
                del write_time[key]
                if key in access_order:
                    access_order.remove(key)

            # If key doesn't exist and cache is full, evict LRU
            if key not in cache:
                if len(cache) >= capacity:
                    # Evict least recently used (first in access_order)
                    lru_key = access_order.pop(0)
                    del cache[lru_key]
                    del write_time[lru_key]

            # Store the value
            cache[key] = value
            write_time[key] = t
            mark_accessed(key)

        elif op[0] == 'get':
            _, t, key = op

            # Check if key exists and is not expired
            if key in cache and not is_expired(key, t):
                results.append(cache[key])
                mark_accessed(key)
            else:
                results.append(-1)

    return results

